python3 << 'EOF'
import csv, re
from collections import Counter

with open('dataset/employees.csv') as f:
    employees = list(csv.DictReader(f))
emp_by_pesel = {e['PESEL']: e for e in employees}

with open('dataset/tasks.csv') as f:
    task_pay = {t['task_id']: int(t['pay_per_completion']) for t in csv.DictReader(f)}

with open('dataset/timesheet.csv') as f:
    ts = list(csv.DictReader(f))

def parse_tasks(s):
    return re.findall(r'\d+', s)

# malformed task list rows
for r in ts:
    s = r['performed_tasks']
    if not (s.startswith('[') and s.endswith(']')):
        print("malformed tasks:", r)

# unknown employee ids - counts per id, and per known id
ids = Counter(r['employee_id'] for r in ts)
print("\nper-id counts:")
for i, c in sorted(ids.items(), key=lambda x: -x[1]):
    mark = '' if i in emp_by_pesel else '  <-- UNKNOWN'
    print(f"  {i}: {c}{mark}")

# unknown task ids
tids = Counter()
for r in ts:
    for t in parse_tasks(r['performed_tasks']):
        tids[t] += 1
print("\nunknown task ids:", {i: c for i, c in tids.items() if i not in task_pay})
print("known task id usage counts:", sorted((c for i,c in tids.items() if i in task_pay)))

# duplicate row ids?
rid = Counter(r['id'] for r in ts)
dups = {i:c for i,c in rid.items() if c>1}
print("\nduplicate 'id' values:", len(dups))
for i in list(dups)[:10]:
    for r in ts:
        if r['id']==i: print("  ", r)
